// Des: M1 gate: launch Chrome, connect, navigate, snapshot fake page
// Flo: launch > navigate data url > read text > AX snapshot > find nodes > stop
// I/O: fake html > pass or fail (skips when no browser)
// Run: zig build test
// ===================================================================
const std = @import("std"); const mock = @import("te-mock-page.zig"); const snap = @import("ru-page-snap.zig"); const fixt = @import("te-fixt-html.zig");
fn profOf(tmpz: *std.testing.TmpDir, buff: []u8) ![]const u8 { return std.fmt.bufPrint(buff, ".zig-cache/tmp/{s}/prof", .{tmpz.sub_path}); }
test "data url encodes reserved bytes and keeps safe ones" { const url = try mock.dataUrl(std.testing.allocator, "a b<#>é"); defer std.testing.allocator.free(url); try std.testing.expectEqualStrings("data:text/html;charset=utf-8,a%20b%3C%23%3E%C3%A9", url); }
test "M1: connect, navigate and snapshot the mock chat page" { const gpa = std.testing.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var mok = try mock.start(gpa, std.testing.io, try profOf(&tmpz, &buff), fixt.chat); defer mok.stop(); var aren = std.heap.ArenaAllocator.init(gpa); defer aren.deinit(); const alo = aren.allocator(); const txt = try snap.pageText(alo, mok.conn); try std.testing.expect(std.mem.find(u8, txt, "Mom") != null); const nodes = try snap.axSnap(alo, mok.conn); try std.testing.expect(snap.findNode(nodes, "textbox", "Tìm kiếm") != null); try std.testing.expect(snap.findNode(nodes, "button", "Gửi") != null); try std.testing.expect(snap.findNode(nodes, "listitem", "mom unread") != null); try std.testing.expect(snap.findNode(nodes, "button", "no such label") == null); const send = snap.findNode(nodes, "button", "Gửi").?; const pt = try snap.boxCenter(alo, mok.conn, send.bid); try std.testing.expect(pt.x > 0 and pt.y > 0); }
test "evalStr returns strings, numbers and bools" { const gpa = std.testing.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var mok = try mock.start(gpa, std.testing.io, try profOf(&tmpz, &buff), fixt.chat); defer mok.stop(); var aren = std.heap.ArenaAllocator.init(gpa); defer aren.deinit(); const alo = aren.allocator(); try std.testing.expectEqualStrings("hé", try snap.evalStr(alo, mok.conn, "'h'+'é'")); try std.testing.expectEqualStrings("42", try snap.evalStr(alo, mok.conn, "6*7")); try std.testing.expectEqualStrings("true", try snap.evalStr(alo, mok.conn, "1<2")); }
test "waitFind returns NoElem for a missing label and the node for a present one" { const gpa = std.testing.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var mok = try mock.start(gpa, std.testing.io, try profOf(&tmpz, &buff), fixt.chat); defer mok.stop(); var aren = std.heap.ArenaAllocator.init(gpa); defer aren.deinit(); try std.testing.expectError(error.NoElem, snap.waitFind(aren.allocator(), mok.conn, "button", "nope", 2)); const got = try snap.waitFind(aren.allocator(), mok.conn, "listitem", "Boss", 2); try std.testing.expect(got.bid > 0); }
